const storageKey = 'flowroute-finance-state-v2';
let state = loadState();
let lastExtractedFile = '';
const fmt = new Intl.NumberFormat('pt-AO', { maximumFractionDigits: 0 });
const dateFmt = new Intl.DateTimeFormat('pt-AO', { day: '2-digit', month: 'short', year: 'numeric' });
const money = value => `${fmt.format(Number(value || 0))} Kz`;
const shortDate = value => value && /^\d{4}-\d{2}-\d{2}$/.test(String(value)) ? dateFmt.format(new Date(`${value}T00:00:00`)).replace('.', '') : (value || '—');
const byId = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function loadState() {
  try { const stored = JSON.parse(localStorage.getItem(storageKey)); if (!stored) return structuredClone(seed); const next = structuredClone(seed); Object.keys(seed).forEach(key => { if (Array.isArray(stored[key])) next[key] = stored[key]; }); return next; } catch { return structuredClone(seed); }
}
function persist() { localStorage.setItem(storageKey, JSON.stringify(state)); updateSync(); }
function updateSync() { const now = new Date(); const t = `Atualizado ${now.toLocaleTimeString('pt-AO', { hour: '2-digit', minute: '2-digit' })}`; if (byId('lastSync')) byId('lastSync').textContent = t; if (byId('footerSync')) byId('footerSync').textContent = `${now.toLocaleDateString('pt-AO', { day: '2-digit', month: 'short', year: 'numeric' })}, ${t.replace('Atualizado ', '')}`; }
function toast(message) { const el = byId('toast'); el.textContent = message; el.classList.add('show'); window.clearTimeout(toast.timer); toast.timer = window.setTimeout(() => el.classList.remove('show'), 3600); }
function defFor(id) { return moduleDefs.find(item => item.id === id); }
function renderNav() { byId('moduleNav').innerHTML = moduleDefs.map(item => `<button class="nav-item ${item.id === 'summary' ? 'active' : ''}" data-module-target="${item.id}"><span class="nav-icon">${item.icon}</span><span>${item.label}</span>${item.id === 'accounting' ? `<span class="nav-badge" id="expenseBadge">${state.expenses.length}</span>` : ''}</button>`).join(''); document.querySelectorAll('[data-module-target]').forEach(btn => btn.addEventListener('click', () => switchModule(btn.dataset.moduleTarget))); }
function switchModule(id) { const item = defFor(id) || defFor('summary'); const isSummary = item.id === 'summary'; byId('view-dashboard').classList.toggle('active', isSummary); byId('view-module').classList.toggle('active', !isSummary); document.querySelectorAll('.nav-item').forEach(btn => btn.classList.toggle('active', btn.dataset.moduleTarget === item.id)); byId('pageTitle').textContent = item.label; if (!isSummary) renderModule(item.id); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function renderAll() { renderNav(); renderSummary(); const active = document.querySelector('.nav-item.active')?.dataset.moduleTarget || 'summary'; if (active !== 'summary') renderModule(active); }

function totals() { const expenses = state.expenses.reduce((sum, row) => sum + Number(row.amount || 0), 0); const maintenance = state.maintenance.filter(row => ['Paga', 'Executada'].includes(row.status)).reduce((sum, row) => sum + Number(row.planned || 0), 0); const paid = state.paymentRegister.reduce((sum, row) => sum + Number(row.amount || 0), 0); const pendingChanges = state.changes.filter(row => row.status === 'Pendente').length; const pendingPurchases = state.purchases.filter(row => row.status !== 'Paga').length; return { expenses, maintenance, paid, pendingChanges, pendingPurchases, realized: expenses + maintenance, balance: Math.max(0, state.budget.total - paid - expenses - maintenance) }; }
function renderSummary() { const t = totals(); byId('metricBudget').textContent = money(state.budget.total); byId('metricSpent').textContent = money(t.realized); byId('expenseCount').textContent = `${state.expenses.length} lançamento${state.expenses.length === 1 ? '' : 's'}`; byId('metricBalance').textContent = money(t.balance); byId('pendingCount').textContent = `${t.pendingChanges + t.pendingPurchases} pendências`; byId('metricSavings').textContent = money(state.budget.savings); renderBars(); renderTeams(); renderLatestExpenses(); renderAttention(); renderShortcuts(); }
function renderBars() { const max = Math.max(...state.budget.categories.map(item => Number(item.expected)), 1); const realized = totals().realized; byId('budgetBars').innerHTML = state.budget.categories.map((item, index) => { const actual = index === 2 ? state.expenses.filter(x => x.type === 'Combustível').reduce((s, x) => s + Number(x.amount || 0), 0) : index === 3 ? totals().maintenance : 0; return `<div class="bar-row"><span class="bar-label">${esc(item.label)}</span><div class="bars"><span class="bar-track"><i class="bar expected" style="width:${Math.max(1, Number(item.expected) / max * 100)}%"></i></span><span class="bar-track"><i class="bar actual" style="width:${actual ? Math.min(100, actual / max * 100) : 0}%"></i></span></div><span class="bar-value">${money(item.expected)}</span></div>`; }).join(''); void realized; }
function renderTeams() { byId('teamList').innerHTML = state.teams.map(team => `<div class="team-item"><div class="team-avatar ${team.color === 'coral' ? 'coral' : ''}">${esc(team.id)}</div><div class="team-main"><strong>${esc(team.mission)}</strong><span>${team.people || '—'} titulares · ${Number(team.km || 0).toLocaleString('pt-AO')} km rodoviários</span></div><div class="team-side"><div class="team-status ${team.status === 'Aprovada' ? 'green' : 'gold'}">${esc(team.status)}</div><div class="team-dates">${team.vehicle || 'Sem viatura'} · ${money(team.total || 0)}</div></div></div>`).join(''); }
function renderLatestExpenses() { byId('latestExpenses').innerHTML = state.expenses.slice().reverse().map(item => `<tr><td><strong>${esc(item.team)}</strong></td><td>${shortDate(item.date)}</td><td>${esc(item.type)}</td><td>${esc(item.supplier || '—')}</td><td class="align-right"><strong>${money(item.amount)}</strong></td></tr>`).join('') || '<tr><td colspan="5">Nenhuma despesa lançada.</td></tr>'; }
function renderAttention() { const rows = []; const pendingChange = state.changes.find(row => row.status === 'Pendente'); if (pendingChange) rows.push(['gold', 'Alteração pendente', `${pendingChange.id} · ${pendingChange.type} · ${pendingChange.team}`, 'changes']); const pendingPurchase = state.purchases.find(row => row.status === 'Aguardando aprovação'); if (pendingPurchase) rows.push(['coral', 'Compra extra aguardando aprovação', `${pendingPurchase.id} · ${pendingPurchase.item}`, 'purchases']); const overdue = state.fleet.find(row => row.status !== 'Em dia'); if (overdue) rows.push(['blue', 'Leitura de frota atrasada', `${overdue.vehicle} · atualize a quilometragem`, 'fleet']); const missing = state.bank.filter(row => row.status !== 'Validada').length; if (missing) rows.push(['blue', `${missing} beneficiário sem conta validada`, 'Complete Dados Bancários antes do pagamento.', 'bank']); byId('alertCount').textContent = rows.length; byId('attentionList').innerHTML = rows.map(row => `<button class="attention-item attention-link" data-module-target="${row[3]}"><span class="attention-icon ${row[0]}">!</span><div><strong>${esc(row[1])}</strong><span>${esc(row[2])}</span></div><span class="arrow">→</span></button>`).join('') || '<div class="empty-state">Nenhuma pendência crítica no momento.</div>'; byId('attentionList').querySelectorAll('[data-module-target]').forEach(btn => btn.addEventListener('click', () => switchModule(btn.dataset.moduleTarget))); }
function renderShortcuts() { byId('moduleShortcuts').innerHTML = moduleDefs.filter(item => item.id !== 'summary').map(item => `<button class="module-shortcut" data-module-target="${item.id}"><span class="shortcut-icon">${item.icon}</span><span><strong>${item.label}</strong><small>${item.kind === 'help' ? 'Fluxo e regras' : item.kind === 'reports' ? 'Excel completo' : 'Abrir módulo'}</small></span><span class="arrow">→</span></button>`).join(''); byId('moduleShortcuts').querySelectorAll('[data-module-target]').forEach(btn => btn.addEventListener('click', () => switchModule(btn.dataset.moduleTarget))); }

function renderModule(id) { if (id === 'instructions') return renderHelp(); if (id === 'reports') return renderReports(); if (id === 'accounting') return renderAccounting(); return renderGeneric(id); }
function moduleHeader(def, actionText = 'Novo registo') { return `<div class="page-heading compact-heading"><div><div class="kicker">MÓDULO ADMINISTRATIVO</div><h1>${def.label}</h1><p>${specs[def.id]?.description || 'Área de trabalho do controlo financeiro PEMx-RNA.'}</p></div><div class="heading-actions"><button class="button secondary" id="moduleExport"><span>↓</span> Exportar módulo</button><button class="button primary" data-scroll-form="true"><span>＋</span> ${actionText}</button></div></div>`; }
function renderHelp() { byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">MÓDULO ADMINISTRATIVO</div><h1>Instruções / Ajuda</h1><p>O fluxo da planilha foi organizado em módulos para uso do administrador.</p></div><span class="admin-badge">Base PEMx-RNA</span></div><div class="help-grid"><article class="panel help-intro"><div class="panel-heading"><div><h2>Como usar o sistema</h2><p>Comece no Resumo e avance pelos módulos na ordem da operação.</p></div><span class="file-icon">?</span></div><div class="help-steps">${['Cadastre parâmetros, funcionários e equipes antes de montar as rotas.', 'Componha cada equipe e defina titulares, reservas e viatura.', 'Lance as rotas por etapas. Cabinda deve ser tratada como deslocamento aéreo.', 'Registe alterações. Apenas uma alteração aprovada atualiza o planeamento.', 'Lance passagens, manutenção, quilometragem e compras extras nos respetivos módulos.', 'Valide dados bancários, registre pagamentos e acompanhe o a pagar.', 'Use Prestação de Contas para combustível e despesas pagas pelo adiantamento.', 'Exporte o relatório Excel completo para o administrador e para a direção.'].map((text, i) => `<div class="help-step"><span>${i + 1}</span><p>${text}</p></div>`).join('')}</div></article><article class="panel rules-panel"><div class="panel-heading"><div><h2>Regras principais</h2><p>Conforme a aba Instruções da planilha de referência.</p></div></div><div class="rule-list"><div><strong>Diárias</strong><span>América: 40 000 Kz/noite. África: 40 000 Kz/noite + 10 000 Kz/dia.</span></div><div><strong>Contingências</strong><span>Reservas só são pagas quando ativadas. Contingência financeira fica separada.</span></div><div><strong>Prestação</strong><span>Combustível e outras despesas entram no acerto. Passagens são pagas diretamente pela empresa.</span></div><div><strong>Segurança</strong><span>Dados bancários ficam restritos ao modo administrador e aparecem mascarados nas tabelas.</span></div></div></article></div>`; }

function rowsFor(id) { const spec = specs[id]; return state[defFor(id)?.stateKey || id] || []; }
function cellValue(value, key) { if (value === undefined || value === null || value === '') return '—'; if (['amount', 'due', 'paid', 'balance', 'planned', 'impact', 'estimated'].includes(key)) return money(value); if (key === 'valueUsd') return `${Number(value || 0).toLocaleString('pt-AO')} USD`; if (['date', 'departure', 'lastReading', 'nextService'].includes(key)) return shortDate(value); return String(value); }
function renderGeneric(id) { const def = defFor(id); const spec = specs[id]; const rows = rowsFor(id); byId('moduleHost').innerHTML = `${moduleHeader(def)}<div class="module-layout"><article class="panel module-table"><div class="panel-heading"><div><h2>Registos</h2><p>${rows.length} registos disponíveis neste ambiente.</p></div><span class="panel-tag">Interativo</span></div><div class="table-scroll"><table class="data-table module-data-table"><thead><tr>${spec.columns.map(col => `<th>${col[1]}</th>`).join('')}<th>Ações</th></tr></thead><tbody>${rows.map((row, index) => `<tr>${spec.columns.map(col => `<td>${col[0] === 'status' || col[0] === 'accountStatus' ? `<span class="status-chip ${String(row[col[0]]).toLowerCase().includes('pend') || String(row[col[0]]).toLowerCase().includes('atras') ? 'warning-chip' : ''}">${esc(cellValue(row[col[0]], col[0]))}</span>` : esc(cellValue(row[col[0]], col[0]))}</td>`).join('')}<td class="row-actions">${actionButtons(id, row, index)}</td></tr>`).join('') || `<tr><td colspan="${spec.columns.length + 1}">Nenhum registo. Use o formulário para adicionar.</td></tr>`}</tbody></table></div></article><article class="panel module-form" id="moduleFormPanel"><div class="panel-heading"><div><h2>Novo registo</h2><p>Os campos ficam guardados neste navegador.</p></div><span class="file-icon">＋</span></div><form class="generic-form" id="genericForm" data-module="${id}">${spec.fields.map(field => `<label>${field[1]}<input name="${field[0]}" type="${field[2]}" ${field[2] === 'number' ? 'inputmode="decimal"' : ''} /></label>`).join('')}<div class="form-actions"><span class="review-note">Campos podem ser editados depois no fluxo.</span><button class="button primary" type="submit">Adicionar registo</button></div></form></article></div>`; bindGeneric(id); }
function actionButtons(id, row, index) { if (id === 'changes' && row.status === 'Pendente') return `<button class="mini-action" data-row-action="approve-change" data-index="${index}">Aprovar</button>`; if (id === 'purchases' && row.status === 'Aguardando aprovação') return `<button class="mini-action" data-row-action="approve-purchase" data-index="${index}">Aprovar</button>`; if (id === 'fleet' && row.status !== 'Em dia') return `<button class="mini-action" data-row-action="mark-fleet" data-index="${index}">Marcar em dia</button>`; return `<button class="icon-button row-action" data-row-action="inspect" data-index="${index}" title="Ver registo">›</button>`; }
function bindGeneric(id) { const form = byId('genericForm'); form?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); const spec = specs[id]; spec.fields.forEach(field => { if (field[2] === 'number' && data[field[0]] !== '') data[field[0]] = Number(String(data[field[0]]).replace(',', '.')); }); const key = defFor(id).stateKey; state[key].push(data); persist(); renderAll(); switchModule(id); toast('Registo adicionado ao módulo.'); }); byId('moduleExport')?.addEventListener('click', () => downloadWorkbook(`PEMx-RNA_${id}`)); document.querySelector('[data-scroll-form]')?.addEventListener('click', () => byId('moduleFormPanel')?.scrollIntoView({ behavior: 'smooth', block: 'center' })); byId('moduleHost').querySelectorAll('[data-row-action]').forEach(button => button.addEventListener('click', () => handleRowAction(id, Number(button.dataset.index), button.dataset.rowAction))); }
function handleRowAction(id, index, action) { if (action === 'approve-change') { state.changes[index].status = 'Aprovada'; toast(`${state.changes[index].id} aprovada. Rotas e orçamento podem ser atualizados.`); } else if (action === 'approve-purchase') { state.purchases[index].status = 'Aprovada'; toast(`${state.purchases[index].id} aprovada para compra.`); } else if (action === 'mark-fleet') { state.fleet[index].status = 'Em dia'; toast(`${state.fleet[index].vehicle} marcada como em dia.`); } else { toast('Registo selecionado para revisão.'); return; } persist(); renderAll(); switchModule(id); }

function renderAccounting() { const t = totals(); byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">MÓDULO ADMINISTRATIVO</div><h1>Prestação de Contas</h1><p>Combustível e outras despesas pagas com o adiantamento. Importe o comprovativo e confirme os dados.</p></div><div class="heading-actions"><button class="button secondary" id="accountingExport"><span>↓</span> Exportar módulo</button><span class="admin-badge">${state.expenses.length} lançamentos</span></div></div><div class="expenses-layout"><article class="panel import-panel"><div class="panel-heading"><div><h2>Importar comprovativo</h2><p>Nota fiscal, fatura, recibo ou comprovativo em imagem/PDF.</p></div><span class="ai-pill"><span class="pulse"></span> OCR assistido</span></div><label class="upload-zone" id="dropZone" for="receiptFile"><input type="file" id="receiptFile" accept="image/*,.pdf,application/pdf" /><span class="upload-icon">↑</span><strong>Arraste o comprovativo para aqui</strong><span>ou clique para escolher · PNG, JPG ou PDF</span><small>Os campos extraídos são sempre revistos antes de gravar.</small></label><div class="extraction-state" id="extractionState"><span class="state-icon">✦</span><div><strong>Aguardando documento</strong><span>O sistema preencherá os campos quando fizer a leitura.</span></div></div><div class="manual-divider"><span>lançamento manual ou revisão do OCR</span></div><form class="expense-form" id="expenseForm"><div class="form-row two"><label>Equipe<select id="expenseTeam"><option>EQ-01</option><option>EQ-02</option><option>EQ-03</option></select></label><label>Data<input id="expenseDate" type="date" value="2026-11-08" required /></label></div><div class="form-row two"><label>Tipo de despesa<select id="expenseType"><option>Combustível</option><option>Portagem / estacionamento</option><option>Táxi / transporte local</option><option>Material / consumíveis</option><option>Outra</option></select></label><label>Valor (AOA)<input id="expenseAmount" inputmode="decimal" placeholder="0" required /></label></div><div class="form-row two"><label>Fornecedor / posto<input id="expenseSupplier" placeholder="Ex.: Sonangol" /></label><label>Nº fatura / recibo<input id="expenseInvoice" placeholder="Ex.: FT A/1001" /></label></div><label>Descrição<input id="expenseDescription" placeholder="Ex.: Gasóleo Luanda–Benguela" /></label><div class="form-row two"><label>Comprovativo anexado<select id="expenseAttachment"><option>Sim</option><option>Não</option></select></label><label>Viatura / observação<input id="expenseNote" placeholder="Ex.: CAM-02" /></label></div><div class="form-actions"><span class="review-note">✦ Campos extraídos ficam editáveis.</span><button type="submit" class="button primary"><span>＋</span> Gravar lançamento</button></div></form></article><article class="panel expense-ledger"><div class="panel-heading"><div><h2>Lançamentos recentes</h2><p>${state.expenses.length} registos · total comprovado ${money(t.expenses)}</p></div><span class="panel-tag">AOA</span></div><div class="table-scroll"><table class="data-table ledger-table"><thead><tr><th>Equipe / data</th><th>Natureza</th><th>Fornecedor</th><th class="align-right">Valor</th><th>Estado</th></tr></thead><tbody>${state.expenses.slice().reverse().map(item => `<tr><td><div class="ledger-team"><strong>${esc(item.team)}</strong><span>${shortDate(item.date)} · ${esc(item.description)}</span></div></td><td>${esc(item.type)}</td><td>${esc(item.supplier || '—')}</td><td class="align-right"><strong>${money(item.amount)}</strong></td><td><span class="status-chip">${esc(item.status || 'Para validar')}</span></td></tr>`).join('')}</tbody></table></div><div class="ledger-footer"><span>Valor total lançado</span><strong>${money(t.expenses)}</strong></div></article></div>`; bindAccounting(); }
function bindAccounting() { byId('accountingExport')?.addEventListener('click', () => downloadWorkbook('Prestacao_Contas')); const dropZone = byId('dropZone'); const fileInput = byId('receiptFile'); dropZone?.addEventListener('dragover', event => { event.preventDefault(); dropZone.classList.add('dragover'); }); dropZone?.addEventListener('dragleave', () => dropZone.classList.remove('dragover')); dropZone?.addEventListener('drop', event => { event.preventDefault(); dropZone.classList.remove('dragover'); if (event.dataTransfer.files[0]) processReceipt(event.dataTransfer.files[0]); }); fileInput?.addEventListener('change', event => { if (event.target.files[0]) processReceipt(event.target.files[0]); }); byId('expenseForm')?.addEventListener('submit', event => { event.preventDefault(); const amount = Number(byId('expenseAmount').value.replace(/[^0-9,.-]/g, '').replace(',', '.')) || 0; if (!amount) return toast('Informe um valor válido antes de gravar.'); state.expenses.push({ id: `EXP-${String(state.expenses.length + 1).padStart(3, '0')}`, team: byId('expenseTeam').value, date: byId('expenseDate').value, type: byId('expenseType').value, description: byId('expenseDescription').value || 'Despesa extra', supplier: byId('expenseSupplier').value, invoice: byId('expenseInvoice').value, amount, attachment: byId('expenseAttachment').value, attachmentName: lastExtractedFile, note: byId('expenseNote').value, status: byId('expenseAttachment').value === 'Sim' ? 'Validado' : 'Para validar' }); persist(); lastExtractedFile = ''; renderAll(); switchModule('accounting'); toast('Lançamento gravado na prestação de contas.'); }); }
async function processReceipt(file) { lastExtractedFile = file.name; const stateEl = byId('extractionState'); stateEl.innerHTML = `<span class="state-icon">◌</span><div><strong>A ler ${esc(file.name)}</strong><span>A extração pode levar alguns segundos. Confirme todos os campos.</span></div>`; let text = ''; try { text = await extractText(file); } catch (error) { console.warn(error); } fillExpenseFields(parseReceiptText(text, file.name)); stateEl.innerHTML = `<span class="state-icon">✓</span><div><strong>${text ? 'Dados extraídos — revisão necessária' : 'Documento carregado — preencha os campos'}</strong><span>${text ? 'Confira valor, fornecedor e número do documento antes de gravar.' : 'OCR indisponível neste navegador. O arquivo ficou associado.'}</span></div>`; toast(text ? 'Comprovativo lido. Revise os campos extraídos.' : 'Comprovativo carregado. Preencha os campos.'); }
async function extractText(file) { if (file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')) return extractPdfText(file); if (!window.Tesseract) await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js'); if (!window.Tesseract) return ''; const result = await window.Tesseract.recognize(file, 'por+eng', { logger: data => { if (data.status === 'recognizing text' && byId('extractionState')) byId('extractionState').querySelector('strong').textContent = `A ler comprovativo · ${Math.round(data.progress * 100)}%`; } }); return result.data.text || ''; }
async function extractPdfText(file) { if (!window.pdfjsLib) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js'); if (!window.pdfjsLib) return ''; window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; const pdf = await window.pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise; let extracted = ''; for (let pageNumber = 1; pageNumber <= Math.min(pdf.numPages, 3); pageNumber += 1) { const page = await pdf.getPage(pageNumber); const content = await page.getTextContent(); extracted += content.items.map(item => item.str || '').join(' ') + '\n'; } return extracted.trim(); }
function loadScript(src) { return new Promise(resolve => { const script = document.createElement('script'); script.src = src; script.onload = resolve; script.onerror = resolve; document.head.appendChild(script); }); }
function parseReceiptText(text, filename) { const raw = text.trim(); const normalized = raw.replace(/\s+/g, ' ').trim(); const amountMatch = normalized.match(/(?:AOA|KZ|Kz|Total|TOTAL)[^\d]{0,20}([\d .]+[,\.]\d{2}|[\d .]{3,})/i); const invoiceMatch = normalized.match(/(?:fatura|factura|recibo|n[ºo°]?)[^A-Z0-9]{0,10}([A-Z0-9][A-Z0-9/\- .]{3,})/i); const dateMatch = normalized.match(/(\d{1,2}[/.\-]\d{1,2}[/.\-]\d{2,4})/); const supplier = raw.split(/\n|\r/).map(x => x.trim()).find(x => x.length > 3 && !/fatura|factura|recibo|total|valor|data/i.test(x)) || ''; return { amount: amountMatch ? amountMatch[1].replace(/\s/g, '').replace(/\.(?=\d{3})/g, '').replace(',', '.') : '', invoice: invoiceMatch ? invoiceMatch[1].trim() : '', date: dateMatch ? normalizeDate(dateMatch[1]) : '', supplier: supplier.slice(0, 70), description: filename ? `Documento importado: ${filename}` : '' }; }
function normalizeDate(value) { const parts = value.split(/[/.\-]/); if (parts.length !== 3) return ''; const [d, m, y] = parts; return `${y.length === 2 ? '20' + y : y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`; }
function fillExpenseFields(parsed) { if (parsed.amount) byId('expenseAmount').value = parsed.amount; if (parsed.invoice) byId('expenseInvoice').value = parsed.invoice; if (parsed.date) byId('expenseDate').value = parsed.date; if (parsed.supplier) byId('expenseSupplier').value = parsed.supplier; if (parsed.description) byId('expenseDescription').value = parsed.description; }

function renderReports() { const t = totals(); byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">ADMINISTRADOR</div><h1>Relatórios financeiros</h1><p>Exporte um workbook Excel com os demonstrativos financeiros e todos os módulos operacionais.</p></div><span class="admin-badge">Acesso de administrador</span></div><div class="report-layout"><article class="panel report-config"><div class="panel-heading"><div><h2>Gerar relatório completo</h2><p>O arquivo inclui Resumo, Instruções, Parâmetros, rotas, frota, pagamentos e prestação.</p></div><span class="file-icon">XLS</span></div><div class="report-fields"><label>Período<select><option>Novembro 2026</option><option>Todos os períodos</option></select></label><label>Escopo<select><option>Todos os módulos</option><option>Somente financeiros</option><option>Somente operação</option></select></label><label>Formato<select disabled><option>Excel (.xlsx)</option></select></label></div><div class="report-includes"><span class="include-title">Demonstrativos incluídos</span><div class="include-grid"><span>✓ Resumo financeiro</span><span>✓ Orçamento por equipe</span><span>✓ Diárias e passagens</span><span>✓ Rotas e alterações</span><span>✓ Frota e quilometragem</span><span>✓ Compras e pagamentos</span><span>✓ Prestação de contas</span><span>✓ Parâmetros e notas</span></div></div><button class="button primary wide" id="generateReport"><span>↓</span> Gerar e baixar relatório</button><div class="export-note">A exportação é gerada localmente com os dados deste navegador.</div></article><article class="panel report-history"><div class="panel-heading"><div><h2>Prévia do resumo</h2><p>Valores que serão enviados para o Excel.</p></div><span class="panel-tag">NOV 2026</span></div><div class="preview-grid"><div><span>Total previsto</span><strong>${money(state.budget.total)}</strong></div><div><span>Subtotal previsto</span><strong>${money(state.budget.subtotal)}</strong></div><div><span>Realizado</span><strong>${money(t.realized)}</strong></div><div><span>A pagar</span><strong>${money(t.balance)}</strong></div></div><div class="history-list"><div class="empty-history"><span>↗</span><div><strong>O próximo download ficará disponível no histórico</strong><span>Os registos ficam guardados apenas no seu dispositivo.</span></div></div></div></article></div>`; byId('generateReport').addEventListener('click', () => downloadWorkbook('PEMx-RNA_Relatorio_Completo')); }

function moduleRowsForExport(id) { if (id === 'instructions') return [['Tópico', 'Descrição'], ['Fluxo', 'Cadastre parâmetros, pessoas e equipes antes de rotas.'], ['Regras', 'Apenas alterações aprovadas atualizam o planeamento.'], ['Prestação', 'Combustível e outras despesas pagas com adiantamento.']]; const spec = specs[id]; if (!spec) return []; return [spec.columns.map(col => col[1]), ...rowsFor(id).map(row => spec.columns.map(col => row[col[0]] ?? ''))]; }
function workbookSheets() { const t = totals(); const sheets = { 'Resumo Financeiro': [['Demonstrativo', 'Valor (AOA)'], ['Total previsto', state.budget.total], ['Subtotal previsto', state.budget.subtotal], ['Contingência financeira', state.budget.contingency], ['Reserva de pessoal', state.budget.personnelReserve], ['Realizado', t.realized], ['A pagar / regularizar', t.balance], ['Economia por rotas diretas', state.budget.savings]] }; moduleDefs.filter(item => item.id !== 'summary' && item.id !== 'reports').forEach(item => { sheets[item.label.slice(0, 31)] = moduleRowsForExport(item.id); }); return sheets; }
function downloadWorkbook(prefix) { const sheets = workbookSheets(); if (window.XLSX) { const workbook = window.XLSX.utils.book_new(); Object.entries(sheets).forEach(([name, rows]) => window.XLSX.utils.book_append_sheet(workbook, window.XLSX.utils.aoa_to_sheet(rows), name.slice(0, 31))); window.XLSX.writeFile(workbook, `${prefix}_${new Date().toISOString().slice(0, 10)}.xlsx`); toast(`Relatório Excel gerado com ${Object.keys(sheets).length} abas.`); return; } const xml = `<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"></Workbook>`; const blob = new Blob([xml], { type: 'application/vnd.ms-excel' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${prefix}_${new Date().toISOString().slice(0, 10)}.xls`; anchor.click(); URL.revokeObjectURL(url); toast('Relatório Excel compatível gerado.'); }

document.addEventListener('click', event => { const target = event.target.closest('[data-module-target]'); if (target && !target.closest('#moduleNav') && !target.closest('#moduleShortcuts') && !target.closest('#attentionList')) switchModule(target.dataset.moduleTarget); });
byId('quickReport')?.addEventListener('click', () => switchModule('reports'));
byId('periodChip')?.addEventListener('click', () => toast('Período ativo: Novembro 2026.'));
renderAll(); updateSync();
